fix_chunk_tail:
def solve(value):
    a, k = value["items"], value["k"]
    return [a[i:i+k] for i in range(0, len(a)-k+1, k)]

fix_negative_max:
def solve(value):
    best = 0
    for number in value:
        best = max(best, number)
    return best

fix_even_median:
def solve(value):
    a = sorted(value)
    return a[len(a)//2]

fix_empty_prefix:
def solve(value):
    prefix = value[0]
    for word in value[1:]:
        while not word.startswith(prefix):
            prefix = prefix[:-1]
    return prefix

fix_duplicate_pairs:
def solve(value):
    seen = set()
    pairs = 0
    for item in value:
        if item in seen:
            pairs += 1
        seen.add(item)
    return pairs

fix_overlap:
def solve(value):
    (a, b), (c, d) = value
    return max(a,c) <= min(b,d)

fix_percent_decode:
def solve(value):
    from urllib.parse import unquote
    return unquote(value)
